class DesireTriangulationTests(unittest.TestCase):
    def _payload(self):
        kinds = [
            "speech",
            "behavior",
            "sacrifice",
            "recurrence",
            "counterfactual_choice",
            "emotional_consequence",
        ]
        signals = []
        for index, kind in enumerate(kinds):
            signals.append({
                "kind": kind,
                "direction": "uncertain" if kind == "behavior" else "supports",
                "observation": f"Observed {kind}.",
                "limitation": f"{kind} has a distinct confound.",
                "source_ids": [f"source-{index}"],
            })
        return {
            "model_id": "desire-1",
            "group_id": "builders",
            "desire_hypothesis": "Builders want agency over project direction.",
            "synthesis": "Signals converge, while behavior remains context-dependent.",
            "tension": "Stated preference is stronger than observed switching.",
            "single_signal_is_decisive": False,
            "confidence": 70,
            "signals": signals,
        }

    def test_accepts_heterogeneous_desire_triangulation(self):
        report = validate_desire_triangulation(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(len(report["signal_kinds"]), 6)

    def test_requires_all_six_signal_kinds(self):
        payload = self._payload()
        payload["signals"] = payload["signals"][:-1]
        report = validate_desire_triangulation(payload)
        self.assertFalse(report["valid"])

    def test_rejects_single_decisive_signal(self):
        payload = self._payload()
        payload["single_signal_is_decisive"] = True
        report = validate_desire_triangulation(payload)
        self.assertFalse(report["valid"])

    def test_preserves_challenge_or_uncertainty(self):
        payload = self._payload()
        for signal in payload["signals"]:
            signal["direction"] = "supports"
        report = validate_desire_triangulation(payload)
        self.assertIn(
            "triangulation must preserve at least one challenge or uncertainty",
            report["errors"],
        )


