class CausalOutcomeAttributionTests(unittest.TestCase):
    def _payload(self):
        return {
            "attribution_id": "attribution-1",
            "mission_id": "mission-1",
            "pre_registered_forecast_id": "forecast-1",
            "observed_outcome": "Target beneficiary delay fell by 30 percent.",
            "outcome_evidence_id": "outcome-1",
            "outcome_status": "success",
            "thesis_status": "underdetermined",
            "thesis_discriminating_evidence": "The first link matched, but a policy change also removed delay.",
            "outcome_success_proves_thesis": False,
            "forecasted_causal_chain": [
                {
                    "prediction_id": "prediction-1",
                    "cause": "Beneficiaries receive earlier eligibility notice.",
                    "mechanism": "Earlier notice permits preparation before the deadline.",
                    "predicted_effect": "Incomplete applications decline.",
                },
                {
                    "prediction_id": "prediction-2",
                    "cause": "Incomplete applications decline.",
                    "mechanism": "Fewer correction rounds reduce processing queues.",
                    "predicted_effect": "Beneficiary delay falls.",
                },
            ],
            "causal_chain_observations": [
                {"prediction_id": "prediction-1", "matched": True, "evidence_id": "measure-1"},
                {"prediction_id": "prediction-2", "matched": True, "evidence_id": "measure-2"},
            ],
            "execution_quality": {"assessment": "adequate", "evidence_id": "execution-audit-1"},
            "exogenous_factors": [
                {
                    "factor_id": "policy-change",
                    "description": "A concurrent policy removed one correction requirement.",
                    "effect": "helped",
                    "anticipated": False,
                    "evidence_id": "policy-record-1",
                }
            ],
            "attribution_hypotheses": [
                {
                    "kind": "mission_thesis",
                    "evidence_for": "Both forecast links moved in the predicted direction.",
                    "evidence_against": "No isolated comparison identifies the notice mechanism.",
                },
                {
                    "kind": "execution_quality",
                    "evidence_for": "Delivery matched the mission contract.",
                    "evidence_against": "Some beneficiaries received notices late.",
                },
                {
                    "kind": "luck",
                    "evidence_for": "The concurrent policy change also reduced correction rounds.",
                    "evidence_against": "Delay improved before the policy reached every region.",
                },
            ],
        }

    def test_accepts_success_without_treating_it_as_thesis_proof(self):
        report = validate_causal_outcome_attribution(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["outcome_status"], "success")
        self.assertEqual(report["thesis_status"], "underdetermined")

    def test_rejects_success_as_automatic_thesis_proof(self):
        payload = self._payload()
        payload["outcome_success_proves_thesis"] = True
        self.assertFalse(validate_causal_outcome_attribution(payload)["valid"])

    def test_requires_observation_of_every_forecasted_causal_link(self):
        payload = self._payload()
        payload["causal_chain_observations"].pop()
        self.assertFalse(validate_causal_outcome_attribution(payload)["valid"])

    def test_requires_thesis_execution_and_luck_as_competing_attributions(self):
        payload = self._payload()
        payload["attribution_hypotheses"] = payload["attribution_hypotheses"][:1]
        self.assertFalse(validate_causal_outcome_attribution(payload)["valid"])


class FailureLayerDiagnosisTests(unittest.TestCase):
    def _payload(self):
        assessments = []
        for layer in (
            "mission_selection",
            "planning",
            "execution",
            "environment",
            "measurement",
        ):
            assessments.append(
                {
                    "layer": layer,
                    "assessment": "execution" == layer and "failed" or "adequate",
                    "expected_condition": f"Pre-registered {layer} condition holds.",
                    "observed_condition": f"Observed {layer} condition was independently checked.",
                    "evidence_id": f"{layer}-evidence",
                    "discriminator": f"Compare the {layer} trace with its frozen requirement.",
                }
            )
        return {
            "diagnosis_id": "failure-diagnosis-1",
            "mission_id": "mission-1",
            "failure_event": "The intended beneficiary outcome did not appear.",
            "failure_evidence_id": "outcome-2",
            "pre_registered_forecast_id": "forecast-1",
            "conclusion": "execution_failure",
            "conclusion_rationale": "The mission and plan were preserved but delivery omitted the required exposure.",
            "failure_automatically_falsifies_mission": False,
            "mission_thesis_falsified": False,
            "layer_assessments": assessments,
        }

    def test_accepts_failure_isolated_to_execution(self):
        report = validate_failure_layer_diagnosis(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["conclusion"], "execution_failure")
        self.assertFalse(report["mission_thesis_falsified"])

    def test_requires_all_five_failure_layers(self):
        payload = self._payload()
        payload["layer_assessments"].pop()
        self.assertFalse(validate_failure_layer_diagnosis(payload)["valid"])

    def test_rejects_automatic_mission_falsification(self):
        payload = self._payload()
        payload["failure_automatically_falsifies_mission"] = True
        self.assertFalse(validate_failure_layer_diagnosis(payload)["valid"])

    def test_thesis_falsification_requires_selection_failure_and_adequate_downstream(self):
        payload = self._payload()
        payload["mission_thesis_falsified"] = True
        self.assertFalse(validate_failure_layer_diagnosis(payload)["valid"])


class PrestructuredFailureAttributionTests(unittest.TestCase):
    def _payload(self):
        contributions = {
            "mission_selection": "contributing",
            "planning": "none",
            "execution": "contributing",
            "environment": "none",
            "measurement": "none",
        }
        return {
            "attribution_protocol_id": "attribution-protocol-1",
            "mission_id": "mission-1",
            "pre_registered_forecast_id": "forecast-1",
            "structure_frozen_at": "2026-07-01T00:00:00Z",
            "outcome_observed_at": "2026-07-10T00:00:00Z",
            "structure_frozen_before_outcome": True,
            "downstream_execution_presumed_cause": False,
            "upstream_selection_exempt": False,
            "responsibility_mode": "shared",
            "conclusion_rationale": "The thesis understated adoption friction and execution skipped one exposure.",
            "layer_attributions": [
                {
                    "layer": layer,
                    "contribution": contribution,
                    "precommitted_question": f"Did {layer} satisfy its frozen condition?",
                    "evidence_for_contribution": f"Evidence potentially implicating {layer}.",
                    "evidence_against_contribution": f"Evidence potentially clearing {layer}.",
                    "evidence_id": f"{layer}-audit",
                }
                for layer, contribution in contributions.items()
            ],
        }

    def test_accepts_shared_causal_responsibility(self):
        report = validate_prestructured_failure_attribution(self._payload())
        self.assertTrue(report["valid"])
        self.assertCountEqual(report["causal_layers"], ["mission_selection", "execution"])

    def test_requires_structure_to_be_frozen_before_outcome(self):
        payload = self._payload()
        payload["structure_frozen_at"] = payload["outcome_observed_at"]
        self.assertFalse(validate_prestructured_failure_attribution(payload)["valid"])

    def test_rejects_default_downstream_blame_or_upstream_exemption(self):
        payload = self._payload()
        payload["downstream_execution_presumed_cause"] = True
        payload["upstream_selection_exempt"] = True
        self.assertFalse(validate_prestructured_failure_attribution(payload)["valid"])

    def test_shared_mode_requires_multiple_causal_layers(self):
        payload = self._payload()
        for layer in payload["layer_attributions"]:
            if layer["layer"] == "mission_selection":
                layer["contribution"] = "none"
        self.assertFalse(validate_prestructured_failure_attribution(payload)["valid"])


