class ConsequenceReviewCadenceTests(unittest.TestCase):
    def _payload(self):
        values = {
            "benefit": ("lagging", 14, 14),
            "harm": ("immediate", 0, 1),
            "sustainability": ("long_horizon", 30, 30),
            "option_preservation": ("early", 7, 7),
        }
        return {
            "cadence_id": "cadence-1",
            "mission_id": "mission-a",
            "uniform_cadence": False,
            "schedule_rationale": "Harm can precede lagging benefit and option loss can become irreversible.",
            "consequence_schedules": [
                {
                    "consequence_type": consequence_type,
                    "expected_latency": latency,
                    "first_review_after_days": first_review,
                    "recurring_interval_days": interval,
                    "wake_trigger": f"Unexpected {consequence_type} signal arrives.",
                    "evidence_source_id": f"{consequence_type}-channel",
                    "latency_rationale": f"{consequence_type} has a distinct observation latency.",
                }
                for consequence_type, (latency, first_review, interval) in values.items()
            ],
        }

    def test_accepts_distinct_early_harm_and_lagging_benefit_schedules(self):
        report = validate_consequence_review_cadence(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["schedule_by_type"]["harm"], (0, 1))

    def test_rejects_uniform_cadence(self):
        payload = self._payload()
        payload["uniform_cadence"] = True
        for schedule in payload["consequence_schedules"]:
            schedule["first_review_after_days"] = 7
            schedule["recurring_interval_days"] = 7
        self.assertFalse(validate_consequence_review_cadence(payload)["valid"])

    def test_requires_all_consequence_types(self):
        payload = self._payload()
        payload["consequence_schedules"].pop()
        self.assertFalse(validate_consequence_review_cadence(payload)["valid"])

    def test_rejects_harm_review_later_than_benefit(self):
        payload = self._payload()
        harm = next(
            schedule for schedule in payload["consequence_schedules"]
            if schedule["consequence_type"] == "harm"
        )
        harm["first_review_after_days"] = 20
        self.assertFalse(validate_consequence_review_cadence(payload)["valid"])


