class GrowthMechanismAuditTests(unittest.TestCase):
    def _payload(self):
        statuses = {
            "voluntary_durable_benefit": "present",
            "switching_friction": "absent",
            "compulsion": "absent",
            "acquired_distribution": "present",
        }
        return {
            "audit_id": "growth-audit-1",
            "mission_id": "mission-a",
            "growth_observation": "Retention and paid adoption increased after institutional distribution.",
            "growth_evidence_id": "growth-cohort-1",
            "growth_is_value_proof": False,
            "mechanism_assessments": [
                {
                    "mechanism": mechanism,
                    "status": status,
                    "observation": f"Sourced observation for {mechanism}.",
                    "evidence_id": f"{mechanism}-evidence",
                    "discriminator": f"Test whether {mechanism} remains after distribution support ends.",
                }
                for mechanism, status in statuses.items()
            ],
            "classification": "durable_benefit",
            "classification_rationale": "Voluntary outcome persists without friction or compulsion.",
            "decision": "scale",
        }

    def test_accepts_growth_with_durable_voluntary_benefit(self):
        report = validate_growth_mechanism_audit(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["classification"], "durable_benefit")

    def test_rejects_growth_as_value_proof(self):
        payload = self._payload()
        payload["growth_is_value_proof"] = True
        self.assertFalse(validate_growth_mechanism_audit(payload)["valid"])

    def test_requires_all_four_growth_mechanisms(self):
        payload = self._payload()
        payload["mechanism_assessments"].pop()
        self.assertFalse(validate_growth_mechanism_audit(payload)["valid"])

    def test_rejects_scaling_when_compulsion_is_present(self):
        payload = self._payload()
        compulsion = next(
            item for item in payload["mechanism_assessments"]
            if item["mechanism"] == "compulsion"
        )
        compulsion["status"] = "present"
        self.assertFalse(validate_growth_mechanism_audit(payload)["valid"])


