class AtomicMissionCycleTests(unittest.TestCase):
    def _payload(self):
        operations = [
            "observe_mismatch",
            "interpret_condition",
            "generate_missions",
            "attack_missions",
            "select_authority_bounded_action",
            "learn_consequence",
        ]
        steps = []
        input_fingerprint = "initial-signal-frontier"
        for index, operation in enumerate(operations, start=1):
            output_fingerprint = f"cycle-state-{index}"
            steps.append(
                {
                    "operation": operation,
                    "artifact_id": f"artifact-{index}",
                    "input_fingerprint": input_fingerprint,
                    "output_fingerprint": output_fingerprint,
                    "evidence_id": f"evidence-{index}",
                    "result": f"Completed {operation}.",
                    "completed": True,
                }
            )
            input_fingerprint = output_fingerprint
        return {
            "cycle_id": "atomic-cycle-1",
            "constitution_id": "company-constitution-v2",
            "started_at": "2026-07-01T00:00:00Z",
            "completed_at": "2026-08-01T00:00:00Z",
            "steps": steps,
            "steps_skipped": [],
        }

    def test_accepts_complete_linked_atomic_cycle(self):
        report = validate_atomic_mission_cycle(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["final_fingerprint"], "cycle-state-6")

    def test_rejects_skipped_operation(self):
        payload = self._payload()
        payload["steps"].pop(3)
        payload["steps_skipped"] = ["attack_missions"]
        self.assertFalse(validate_atomic_mission_cycle(payload)["valid"])

    def test_rejects_out_of_order_operation(self):
        payload = self._payload()
        payload["steps"][1], payload["steps"][2] = payload["steps"][2], payload["steps"][1]
        self.assertFalse(validate_atomic_mission_cycle(payload)["valid"])

    def test_requires_fingerprint_lineage_between_steps(self):
        payload = self._payload()
        payload["steps"][4]["input_fingerprint"] = "unrelated-state"
        self.assertFalse(validate_atomic_mission_cycle(payload)["valid"])


