class DecisionRelevantCausalComplexityTests(unittest.TestCase):
    def _payload(self):
        components = []
        details = {
            "actor": ("Deadline-bound applicant", "determines who bears delay"),
            "incentive": ("Completion metric pressure", "changes whether pauses are resisted"),
            "constraint": ("Eligibility deadline", "changes reversible delay into irreversible loss"),
            "mechanism": ("Read-only fallback", "changes whether access survives a pause"),
            "feedback_loop": ("Failure-retry overload", "changes whether degradation amplifies"),
        }
        for index, (component_type, (description, relevance)) in enumerate(details.items(), 1):
            components.append(
                {
                    "component_id": f"component-{index}",
                    "component_type": component_type,
                    "description": description,
                    "decision_relevance": relevance,
                    "changed_decision_branch": f"Changes branch for {component_type} mitigation.",
                    "evidence_id": f"evidence-{index}",
                    "removal_consequence": f"Removing {component_type} reverses or obscures the selected probe.",
                    "removal_leaves_decision_unchanged": False,
                }
            )
        return {
            "complexity_review_id": "complexity-review-1",
            "causal_sketch_id": "sketch-connectivity",
            "target_decision": "Run resumability, language, or combined mechanism probe.",
            "decorative_complexity_allowed": False,
            "component_budget": 7,
            "components": components,
            "pruning_rule": "Remove any component that cannot change a decision branch.",
        }

    def test_accepts_five_decision_relevant_component_types(self):
        report = validate_decision_relevant_causal_complexity(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(len(report["represented_component_types"]), 5)

    def test_rejects_decorative_or_decision_inert_component(self):
        payload = self._payload()
        payload["decorative_complexity_allowed"] = True
        payload["components"][0]["removal_leaves_decision_unchanged"] = True
        self.assertFalse(validate_decision_relevant_causal_complexity(payload)["valid"])

    def test_requires_all_causal_component_types(self):
        payload = self._payload()
        payload["components"].pop()
        self.assertFalse(validate_decision_relevant_causal_complexity(payload)["valid"])

    def test_enforces_complexity_budget_and_evidence(self):
        payload = self._payload()
        payload["component_budget"] = 4
        payload["components"][1]["evidence_id"] = ""
        self.assertFalse(validate_decision_relevant_causal_complexity(payload)["valid"])


