class HistoricalMechanismAnalogyTests(unittest.TestCase):
    def _payload(self):
        differences = []
        details = {
            "timing": ("Annual paper enrollment", "Continuous digital enrollment", "Feedback and deadline cadence differ."),
            "institution": ("Single public agency", "Federated public-private operators", "Enforcement and incentives differ."),
            "scale": ("Ten thousand applicants", "Ten million applicants", "Operational bottlenecks may not transfer."),
            "beneficiary_power": ("Union-mediated appeals", "Mostly individual appeals", "Correction leverage is substantially weaker."),
        }
        for dimension, (historical, current, effect) in details.items():
            differences.append(
                {
                    "dimension": dimension,
                    "historical_state": historical,
                    "current_state": current,
                    "effect_on_transfer": effect,
                }
            )
        return {
            "historical_analogy_id": "historical-analogy-1",
            "historical_case_id": "case-paper-resumability",
            "current_case_id": "case-digital-access",
            "historical_outcome": "Saved partial applications reduced deadline abandonment.",
            "candidate_mechanism": "Preserve partial progress across interrupted attempts.",
            "historical_analogy_is_forecast": False,
            "transfer_authority": "mechanism_candidate_only",
            "mechanism_transfer_rationale": "Both cases lose accumulated effort after interruption.",
            "context_differences": differences,
            "local_evidence_ids": ["session-loss-analysis-1", "applicant-interviews-2"],
            "local_probe_id": "resumability-probe-1",
            "local_probe_prediction": "Resumability selectively reduces interruption-linked abandonment.",
            "local_failure_signal": "Abandonment remains unchanged despite verified state preservation.",
        }

    def test_accepts_history_as_mechanism_candidate_only(self):
        report = validate_historical_mechanism_analogy(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(len(report["difference_dimensions"]), 4)

    def test_rejects_historical_analogy_as_forecast(self):
        payload = self._payload()
        payload["historical_analogy_is_forecast"] = True
        payload["transfer_authority"] = "forecast"
        self.assertFalse(validate_historical_mechanism_analogy(payload)["valid"])

    def test_requires_all_four_context_differences(self):
        payload = self._payload()
        payload["context_differences"].pop()
        self.assertFalse(validate_historical_mechanism_analogy(payload)["valid"])

    def test_requires_local_evidence_probe_and_failure_signal(self):
        payload = self._payload()
        payload["local_evidence_ids"] = []
        payload["local_probe_id"] = ""
        payload["local_failure_signal"] = ""
        self.assertFalse(validate_historical_mechanism_analogy(payload)["valid"])


