class SkepticalMissionTranslationTests(unittest.TestCase):
    def _payload(self):
        semantics = {
            "beneficiary": "Applicants with intermittent connectivity near deadlines.",
            "current_condition": "Interrupted sessions can cause permanent eligibility loss.",
            "target_condition": "Interrupted applicants retain a completeable eligibility path.",
            "outcome_measure": "Eligibility retention among verified interrupted applicants.",
            "evaluation_horizon": "Two eligibility cycles.",
        }
        return {
            "translation_test_id": "translation-test-1",
            "mission_candidate_id": "mission-external-condition-1",
            "original_mission_statement": "Build a bridge across the digital eligibility cliff.",
            "removed_creative_terms": ["bridge", "cliff"],
            "skeptical_translator_id": "skeptical-planner-1",
            "translator_saw_generation_context": False,
            "plain_translation": "Interrupted applicants retain eligibility through the deadline.",
            "creative_metaphor_retained": False,
            "original_semantics": semantics,
            "translated_semantics": semantics.copy(),
            "beneficiary_change_preserved": True,
            "translation_status": "passed",
            "translation_rationale": "The plain statement preserves beneficiary, state change, measure, and horizon.",
        }

    def test_accepts_plain_translation_with_identical_beneficiary_change(self):
        report = validate_skeptical_mission_translation(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["translation_status"], "passed")

    def test_rejects_translator_exposed_to_generation_context(self):
        payload = self._payload()
        payload["translator_saw_generation_context"] = True
        self.assertFalse(validate_skeptical_mission_translation(payload)["valid"])

    def test_rejects_retained_metaphor_or_missing_removed_terms(self):
        payload = self._payload()
        payload["creative_metaphor_retained"] = True
        payload["removed_creative_terms"] = []
        self.assertFalse(validate_skeptical_mission_translation(payload)["valid"])

    def test_detects_changed_beneficiary_semantics(self):
        payload = self._payload()
        payload["translated_semantics"]["beneficiary"] = "All active users."
        self.assertFalse(validate_skeptical_mission_translation(payload)["valid"])
        payload["beneficiary_change_preserved"] = False
        payload["translation_status"] = "failed"
        self.assertTrue(validate_skeptical_mission_translation(payload)["valid"])


