class CompetingProbeSelectionTests(unittest.TestCase):
    def _payload(self):
        return {
            "probe_tournament_id": "probe-tournament-1",
            "mission_tournament_id": "mission-tournament-1",
            "leading_mission_ids": ["mission-resumability", "mission-comprehension"],
            "existing_evidence_review_id": "evidence-review-1",
            "probe_candidates": [
                {
                    "probe_id": "safe-fast-probe",
                    "observation": "Observe which intervention restores completion.",
                    "separates_mission_ids": ["mission-resumability", "mission-comprehension"],
                    "answerable_by_existing_evidence": False,
                    "existing_evidence_gap": "No intervention comparison exists.",
                    "harm_score": 0.1,
                    "time_to_observation_hours": 8,
                    "safety_boundary": "No participant loses existing access.",
                    "evidence_id": "probe-design-evidence-1",
                },
                {
                    "probe_id": "slower-probe",
                    "observation": "Observe the same mechanisms over a longer window.",
                    "separates_mission_ids": ["mission-resumability", "mission-comprehension"],
                    "answerable_by_existing_evidence": False,
                    "existing_evidence_gap": "No longitudinal comparison exists.",
                    "harm_score": 0.1,
                    "time_to_observation_hours": 24,
                    "safety_boundary": "No participant loses existing access.",
                    "evidence_id": "probe-design-evidence-2",
                },
            ],
            "selection_status": "selected",
            "selected_probe_id": "safe-fast-probe",
            "selection_rationale": "Both are equally safe, so the faster unanswered separator wins.",
        }

    def test_accepts_least_harmful_then_fastest_unanswered_separator(self):
        report = validate_competing_probe_selection(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["selected_probe_id"], "safe-fast-probe")

    def test_excludes_probe_answerable_by_existing_evidence(self):
        payload = self._payload()
        payload["probe_candidates"][0]["answerable_by_existing_evidence"] = True
        payload["selected_probe_id"] = "slower-probe"
        self.assertTrue(validate_competing_probe_selection(payload)["valid"])

    def test_rejects_probe_that_does_not_separate_all_leading_missions(self):
        payload = self._payload()
        payload["probe_candidates"][0]["separates_mission_ids"].pop()
        payload["selected_probe_id"] = "slower-probe"
        self.assertFalse(validate_competing_probe_selection(payload)["valid"])

    def test_rejects_dominated_selection_and_exposes_exact_tie(self):
        payload = self._payload()
        payload["selected_probe_id"] = "slower-probe"
        self.assertFalse(validate_competing_probe_selection(payload)["valid"])
        payload = self._payload()
        payload["probe_candidates"][1]["time_to_observation_hours"] = 8
        payload["selection_status"] = "unresolved_tie"
        payload["selected_probe_id"] = ""
        self.assertTrue(validate_competing_probe_selection(payload)["valid"])


