class TimedSuccessHarmSignalsTests(unittest.TestCase):
    def _payload(self):
        return {
            "signal_contract_id": "signal-contract-1",
            "planner_contract_id": "planner-contract-1",
            "success_signals": [
                {
                    "signal_id": "verified-resumption-rate",
                    "description": "Share of interrupted eligible applicants who resume.",
                    "unit": "proportion",
                    "baseline_value": 0.1,
                    "baseline_evidence_id": "baseline-evidence-1",
                    "target_range_min": 0.5,
                    "target_range_max": 0.7,
                    "improvement_direction": "increase",
                    "observation_start_day": 14,
                    "observation_end_day": 42,
                    "evidence_source_id": "outcome-source-1",
                }
            ],
            "harm_signals": [
                {
                    "signal_id": "unauthorized-state-exposure",
                    "description": "Applicant state becomes visible outside authorized access.",
                    "threshold": "Any confirmed exposure",
                    "first_review_day": 1,
                    "damage_can_precede_benefit": True,
                    "evidence_source_id": "security-audit-1",
                    "response": "Pause the intervention and return control for harm review.",
                }
            ],
            "schedule_rationale": "Exposure can occur before enough resumptions exist to estimate benefit.",
        }

    def test_accepts_baselined_range_and_earlier_harm_review(self):
        report = validate_timed_success_harm_signals(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["earliest_success_day"], 14)

    def test_success_requires_baseline_target_range_and_time_range(self):
        payload = self._payload()
        signal = payload["success_signals"][0]
        signal["baseline_evidence_id"] = ""
        signal["target_range_min"] = 0.8
        signal["target_range_max"] = 0.6
        signal["observation_end_day"] = signal["observation_start_day"]
