    def test_requires_distinct_freedoms_forbidden_actions_and_trigger_types(self):
        payload = self._payload()
        payload["forbidden_actions"][0] = payload["delegated_freedoms"][0]
        payload["return_triggers"][1]["trigger_type"] = "evidence_change"
