        payload["current_control"] = "palamedes_review"
        self.assertTrue(validate_planner_authority_return_contract(payload)["valid"])
        payload["planner_continues_unilaterally"] = True
        self.assertFalse(validate_planner_authority_return_contract(payload)["valid"])


