class WakeCognitiveOperationSelectionTests(unittest.TestCase):
    def _payload(self):
        return {
            "operation_selection_id": "operation-selection-1",
            "wake_event_id": "wake-event-1",
            "frontier_entry_id": "assumption-state-continuity",
            "observed_insufficiency": "The causal mechanism no longer predicts the observed signal trajectory.",
            "insufficiency_evidence_id": "causal-mismatch-evidence-1",
            "fixed_pipeline_from_scratch": False,
            "operation_options": [
                {
                    "operation": "revise_causal_model",
                    "directly_addresses_insufficiency": True,
                    "fit_rationale": "The evidence contradicts the active mechanism rather than lacking observations.",
                    "expected_update": "Replace or bound the state-continuity mechanism.",
                    "nonselection_reason": "selected",
                },
                {
                    "operation": "observe",
                    "directly_addresses_insufficiency": False,
                    "fit_rationale": "The existing observation already crosses the registered discriminator.",
                    "expected_update": "Would add redundant samples without repairing the model.",
                    "nonselection_reason": "Existing evidence is sufficient to expose the causal mismatch.",
                },
                {
                    "operation": "generate_candidate",
                    "directly_addresses_insufficiency": False,
                    "fit_rationale": "Mission generation is premature before revising the failed mechanism.",
                    "expected_update": "Would expand options without explaining the observed mismatch.",
                    "nonselection_reason": "Repair the causal account before generating new missions.",
                },
            ],
            "selected_operation": "revise_causal_model",
            "operation_sequence": ["revise_causal_model"],
            "selection_rationale": "One model revision directly matches the evidenced insufficiency.",
        }

    def test_accepts_one_operation_selected_from_observed_insufficiency(self):
        report = validate_wake_cognitive_operation_selection(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["selected_operation"], "revise_causal_model")

    def test_rejects_no_fit_or_multiple_direct_fits(self):
        payload = self._payload()
        payload["operation_options"][0]["directly_addresses_insufficiency"] = False
        self.assertFalse(validate_wake_cognitive_operation_selection(payload)["valid"])
        payload = self._payload()
        payload["operation_options"][1]["directly_addresses_insufficiency"] = True
        payload["operation_options"][1]["nonselection_reason"] = "selected"
        self.assertFalse(validate_wake_cognitive_operation_selection(payload)["valid"])

    def test_selected_operation_must_match_unique_fit(self):
        payload = self._payload()
        payload["selected_operation"] = "observe"
        self.assertFalse(validate_wake_cognitive_operation_selection(payload)["valid"])

    def test_rejects_full_pipeline_or_extra_operation_sequence(self):
        payload = self._payload()
        payload["fixed_pipeline_from_scratch"] = True
        payload["operation_sequence"].append("generate_candidate")
        self.assertFalse(validate_wake_cognitive_operation_selection(payload)["valid"])


