class BeneficiaryAuthenticityAssessmentTests(unittest.TestCase):
    def _payload(self):
        observations = {
            "identity": "The same verified beneficiary controls the account across observations.",
            "cost": "Expressing the preference required a consequential time commitment.",
            "recurrence": "The behavior recurred across three separated observation windows.",
            "independent_context": "A separate offline context shows the same constraint.",
        }
        return {
            "authenticity_assessment_id": "authenticity-assessment-1",
            "beneficiary_claim_id": "beneficiary-preference-1",
            "behavior_cluster_id": "behavior-cluster-1",
            "authenticity_dimensions": [
                {
                    "dimension": dimension,
                    "observation": observation,
                    "evidence_id": f"{dimension}-evidence-1",
                    "strength": 0.8,
                    "limitation": f"{dimension} evidence can still be coordinated or simulated.",
                }
                for dimension, observation in observations.items()
            ],
            "coordinated_synthetic_behavior_risk": 0.25,
            "coordination_risk_evidence_id": "coordination-risk-evidence-1",
            "provisional_authenticity_confidence": 0.6,
            "provisional_weight_threshold": 0.55,
            "authenticity_guaranteed": False,
            "residual_uncertainty": "Coordinated actors may still reproduce all four signals.",
            "monitoring_trigger": "Wake if identity clusters or context independence materially change.",
            "decision": "provisionally_weight",
            "assessment_rationale": "Four dimensions support provisional use without proving authenticity.",
        }

    def test_accepts_four_dimensional_provisional_authenticity_weight(self):
        report = validate_beneficiary_authenticity_assessment(self._payload())
        self.assertTrue(report["valid"])
        self.assertAlmostEqual(report["provisional_authenticity_confidence"], 0.6)

    def test_requires_all_four_dimensions_with_evidence_and_limitations(self):
        payload = self._payload()
        payload["authenticity_dimensions"].pop()
        payload["authenticity_dimensions"][0]["limitation"] = ""
        self.assertFalse(validate_beneficiary_authenticity_assessment(payload)["valid"])

    def test_authenticity_can_never_be_guaranteed(self):
        payload = self._payload()
        payload["authenticity_guaranteed"] = True
        self.assertFalse(validate_beneficiary_authenticity_assessment(payload)["valid"])

    def test_coordination_risk_must_discount_confidence_and_decision(self):
        payload = self._payload()
        payload["coordinated_synthetic_behavior_risk"] = 0.75
        payload["provisional_authenticity_confidence"] = 0.2
        payload["decision"] = "downweight_and_probe"
        self.assertTrue(validate_beneficiary_authenticity_assessment(payload)["valid"])
        payload["provisional_authenticity_confidence"] = 0.8
        self.assertFalse(validate_beneficiary_authenticity_assessment(payload)["valid"])


