        payload = self._payload()
        payload["conditions"][0]["compute_report"]["human_work_seconds"] = -1
        payload["conditions"][1]["compute_report"]["measured_not_imputed"] = False
        payload["compute_silently_equalized"] = True
        payload["compute_reported_separately"] = False
        self.assertFalse(validate_equal_information_separate_compute_comparison(payload)["valid"])


