class HumanUpstreamLaborLedgerTests(unittest.TestCase):
    def _payload(self):
        categories = ("framing", "clarification", "approval", "correction", "intervention")
        counts = {
            "human": (1, 2, 1, 1, 0),
            "one_shot_agent": (1, 2, 1, 2, 1),
            "palamedes": (1, 1, 1, 0, 0),
        }
        records = []
        for condition_id in ("human", "one_shot_agent", "palamedes"):
            labor = []
            for category, count in zip(categories, counts[condition_id]):
                labor.append({
                    "category": category,
                    "event_count": count,
                    "human_seconds": count * 60,
                    "evidence_ids": [
                        f"{condition_id}-{category}-{index}" for index in range(count)
                    ],
                })
            records.append({
                "condition_id": condition_id,
                "viable_mission_id": f"viable-{condition_id}",
                "viability_decided_at": "2026-08-08T03:00:00Z",
                "viability_evidence_id": f"viability-{condition_id}",
                "labor_categories": labor,
                "reported_total_event_count": sum(counts[condition_id]),
                "reported_total_human_seconds": sum(counts[condition_id]) * 60,
            })
        return {
            "labor_ledger_id": "upstream-labor-1",
            "case_id": "interrupted-access-case",
            "condition_labor_records": records,
            "zero_labor_must_be_explicit": True,
            "post_viability_labor_included": False,
            "measurement_rationale": "Count all human work needed before each viable mission exists.",
        }

    def test_accepts_five_category_labor_accounting_for_every_condition(self):
        report = validate_human_upstream_labor_ledger(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["human_seconds_by_condition"]["palamedes"], 180)

    def test_requires_all_three_conditions_and_all_five_categories(self):
        payload = self._payload()
        payload["condition_labor_records"].pop()
        payload["condition_labor_records"][0]["labor_categories"].pop()
        self.assertFalse(validate_human_upstream_labor_ledger(payload)["valid"])

    def test_requires_unique_evidence_for_every_counted_human_event(self):
        payload = self._payload()
        payload["condition_labor_records"][1]["labor_categories"][1]["evidence_ids"].pop()
        self.assertFalse(validate_human_upstream_labor_ledger(payload)["valid"])

    def test_rejects_hidden_zeroes_wrong_totals_or_post_viability_labor(self):
        payload = self._payload()
        payload["condition_labor_records"][2]["reported_total_human_seconds"] = 0
        payload["zero_labor_must_be_explicit"] = False
        payload["post_viability_labor_included"] = True
        self.assertFalse(validate_human_upstream_labor_ledger(payload)["valid"])


class PurposeComparisonFailureCriteriaTests(unittest.TestCase):
    def _payload(self):
        labels = {
            "generic_mission": "Mission is indistinguishable from a domain-neutral aspiration.",
            "hidden_human_goal_injection": "Unreported human input supplies a decision-relevant goal.",
            "proxy_harm": "Metric improvement shifts material harm to a beneficiary or hidden party.",
            "constitution_theater": "Selected mission violates a frozen principle despite nominal citation.",
            "planner_reconstruction": "Planner must infer or replace the mission's beneficiary meaning.",
            "no_outcome_advantage": "Palamedes produces no preregistered outcome advantage over baselines.",
        }
        return {
            "failure_protocol_id": "failure-protocol-1",
            "case_id": "interrupted-access-case",
            "failure_criteria": [
                {
                    "criterion_id": f"failure-{failure_type}",
                    "failure_type": failure_type,
                    "observable_test": observable,
                    "failure_threshold": f"Fail when the registered {failure_type} test is met.",
                    "evidence_id": f"failure-evidence-{index}",
                    "independent_evaluator_id": f"blinded-evaluator-{index}",
                    "finding": "The failure threshold was not met.",
                    "triggered": False,
                }
                for index, (failure_type, observable) in enumerate(labels.items(), 1)
            ],
            "overall_verdict": "eligible_for_proof",
            "failure_can_be_offset_by_other_scores": False,
            "criteria_frozen_before_evaluation": True,
            "decision_rationale": "Any core validity failure defeats the purpose-comparison claim.",
        }

    def test_accepts_frozen_observable_untriggered_six_failure_protocol(self):
        report = validate_purpose_comparison_failure_criteria(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["overall_verdict"], "eligible_for_proof")

    def test_requires_exactly_all_six_failure_types(self):
        payload = self._payload()
        payload["failure_criteria"].pop()
        payload["failure_criteria"][0]["failure_type"] = "novelty_shortfall"
        self.assertFalse(validate_purpose_comparison_failure_criteria(payload)["valid"])

    def test_triggered_failure_requires_overall_failure(self):
        payload = self._payload()
        payload["failure_criteria"][2]["triggered"] = True
        self.assertFalse(validate_purpose_comparison_failure_criteria(payload)["valid"])
        payload["overall_verdict"] = "fail"
        self.assertTrue(validate_purpose_comparison_failure_criteria(payload)["valid"])

    def test_rejects_unobservable_unfrozen_or_offsettable_failure_rules(self):
        payload = self._payload()
        payload["failure_criteria"][3]["observable_test"] = ""
        payload["criteria_frozen_before_evaluation"] = False
        payload["failure_can_be_offset_by_other_scores"] = True
        self.assertFalse(validate_purpose_comparison_failure_criteria(payload)["valid"])


