class NarrowCognitiveCommandApiThesisTests(unittest.TestCase):
    def _payload(self):
        specifications = [
            ("record_signal", "validate_record_signal_command", [], "signal"),
            ("evaluate_wake", "validate_evaluate_wake_command", ["signal"], "wake_evaluation"),
            (
                "record_competing_causal_sketches",
                "validate_record_competing_causal_sketches",
                ["signal", "wake_evaluation"],
                "causal_sketch_set",
            ),
            (
                "freeze_pre_rival_mission_forecasts",
                "validate_pre_rival_mission_forecast_freeze",
                ["causal_sketch_set"],
                "frozen_mission_forecast_set",
            ),
            (
                "record_mission_critiques",
                "validate_nonmutating_mission_critique",
                ["frozen_mission_forecast_set"],
                "mission_critique_set",
            ),
            (
                "select_mission_mode",
                "validate_four_mode_mission_selection",
                ["frozen_mission_forecast_set", "mission_critique_set"],
                "mission_selection",
            ),
            (
                "issue_mission_contract",
                "validate_governed_mission_contract_issue",
                ["mission_selection"],
                "mission_contract",
            ),
            (
                "record_mission_outcome",
                "validate_nonrewriting_mission_outcome_record",
                ["mission_contract"],
                "mission_outcome",
            ),
        ]
        return {
            "api_thesis_id": "narrow-cognitive-api-v1",
            "command_registry_id": "purpose-command-registry-v2",
            "revision_envelope_adapter_id": "shared-kernel-adapter-v1",
            "commands": [
                {
                    "ordinal": index,
                    "command": command,
                    "intent": f"Perform only the bounded {command} transition.",
                    "semantic_validator_id": validator,
                    "required_input_artifact_types": inputs,
                    "precondition_expression": "All named input IDs, fingerprints, schemas, and authorities validate.",
                    "authority_id": "purpose-governance",
                    "output_artifact_type": output,
                    "inspectable_output": {
                        "artifact_id": f"artifact-{index}",
                        "artifact_type": output,
                        "schema_id": f"schema:{output}:v1",
                        "fingerprint": f"sha256:artifact-{index}",
                        "provenance_record_id": f"provenance-{index}",
                        "independently_retrievable": True,
                        "independently_validatable": True,
                    },
                    "preconditions_checked_before_execution": True,
                    "hidden_state_transition": False,
                    "implicit_downstream_execution": False,
                }
                for index, (command, validator, inputs, output) in enumerate(specifications, start=1)
            ],
            "generic_create_endpoint_exposed": False,
            "commands_may_skip_preconditions": False,
            "intermediate_artifacts_collapsed": False,
            "model_may_mutate_hidden_state": False,
            "outcome_may_rewrite_history": False,
            "api_thesis_decision": "integrated",
            "thesis_rationale": "Narrow commands make every cognitive transition explicit and reconstructable.",
        }

    def test_accepts_exact_cognitive_sequence_with_inspectable_artifacts(self):
        report = validate_narrow_cognitive_command_api_thesis(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["command_count"], 8)
        self.assertEqual(report["inspectable_artifact_count"], 8)

    def test_rejects_reordering_skipping_or_wrong_semantic_validator(self):
        payload = self._payload()
        payload["commands"][1], payload["commands"][2] = payload["commands"][2], payload["commands"][1]
        payload["commands"][4]["semantic_validator_id"] = "generic_validator"
        self.assertFalse(validate_narrow_cognitive_command_api_thesis(payload)["valid"])

    def test_requires_independently_retrievable_schema_fingerprint_and_provenance(self):
        payload = self._payload()
        output = payload["commands"][3]["inspectable_output"]
        output["schema_id"] = ""
        output["fingerprint"] = ""
        output["provenance_record_id"] = ""
        output["independently_retrievable"] = False
        output["independently_validatable"] = False
        self.assertFalse(validate_narrow_cognitive_command_api_thesis(payload)["valid"])

    def test_rejects_generic_hidden_implicit_or_history_rewriting_paths(self):
        payload = self._payload()
        payload["generic_create_endpoint_exposed"] = True
        payload["commands"][0]["hidden_state_transition"] = True
        payload["commands"][5]["implicit_downstream_execution"] = True
        payload["outcome_may_rewrite_history"] = True
        self.assertFalse(validate_narrow_cognitive_command_api_thesis(payload)["valid"])


class ModelMultiplicityTradeoffTests(unittest.TestCase):
    def _call(self, call_id, model_id, provider_id, tokens, cost):
        return {
            "call_id": call_id,
            "model_id": model_id,
            "provider_id": provider_id,
            "prompt_fingerprint": f"sha256:prompt-{call_id}",
            "response_fingerprint": f"sha256:response-{call_id}",
            "token_count": tokens,
            "cost_usd": cost,
        }

    def _payload(self):
        single_calls = [
            self._call("single-interpret", "model-a", "provider-a", 400, 0.04),
            self._call("single-critique", "model-a", "provider-a", 500, 0.05),
        ]
        multi_calls = [
            self._call("multi-interpret", "model-a", "provider-a", 400, 0.04),
            self._call("multi-critique", "model-b", "provider-b", 500, 0.08),
        ]
        return {
            "tradeoff_id": "multiplicity-tradeoff-1",
            "cognitive_case_id": "case-recourse-mission",
            "frozen_input_fingerprint": "sha256:frozen-case-input",
            "conditions": [
                {
                    "condition_id": "condition-single",
                    "mode": "single_model",
                    "input_fingerprint": "sha256:frozen-case-input",
                    "assignment_manifest_id": "manifest-single",
                    "assignment_manifest_fingerprint": "sha256:manifest-single",
                    "output_artifact_id": "output-single",
                    "model_calls": single_calls,
                    "resource_ledger": {"total_calls": 2, "total_tokens": 900, "total_cost_usd": 0.09},
                    "frame_diversity_score": 0.45,
                    "cross_run_reproducibility_score": 0.91,
                    "measurement_method": "Blind frame clustering and repeated-run overlap.",
                },
                {
                    "condition_id": "condition-multi",
                    "mode": "multi_model",
                    "input_fingerprint": "sha256:frozen-case-input",
                    "assignment_manifest_id": "manifest-multi",
                    "assignment_manifest_fingerprint": "sha256:manifest-multi",
                    "output_artifact_id": "output-multi",
                    "model_calls": multi_calls,
                    "resource_ledger": {"total_calls": 2, "total_tokens": 900, "total_cost_usd": 0.12},
                    "frame_diversity_score": 0.71,
                    "cross_run_reproducibility_score": 0.73,
                    "measurement_method": "Blind frame clustering and repeated-run overlap.",
                },
            ],
            "same_task_and_input": True,
            "same_non_model_budget": True,
            "diversity_assumed_better": False,
            "cost_ignored": False,
            "reproducibility_ignored": False,
            "selection_rule": {
                "minimum_diversity_gain": 0.15,
                "maximum_cost_multiplier": 1.5,
                "minimum_reproducibility": 0.7,
                "fallback": "Use single-model assignment when the multi-model condition misses any threshold.",
            },
            "evaluation_rationale": "Measure diversity benefit against reproducibility and cost rather than assuming it.",
        }

    def test_accepts_same_input_single_and_multi_model_comparison_with_resource_ledgers(self):
        report = validate_model_multiplicity_tradeoff(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["condition_modes"], ["multi_model", "single_model"])

    def test_requires_one_model_in_single_condition_and_multiple_in_multi_condition(self):
        payload = self._payload()
        payload["conditions"][0]["model_calls"][1]["model_id"] = "model-b"
        payload["conditions"][1]["model_calls"][1]["model_id"] = "model-a"
        self.assertFalse(validate_model_multiplicity_tradeoff(payload)["valid"])

    def test_requires_frozen_equal_inputs_distinct_manifests_and_exact_resource_accounting(self):
        payload = self._payload()
        payload["conditions"][1]["input_fingerprint"] = "sha256:different"
        payload["conditions"][1]["assignment_manifest_fingerprint"] = "sha256:manifest-single"
        payload["conditions"][1]["resource_ledger"]["total_tokens"] = 1
        self.assertFalse(validate_model_multiplicity_tradeoff(payload)["valid"])

    def test_cannot_assume_diversity_or_ignore_cost_and_reproducibility(self):
        payload = self._payload()
        payload["diversity_assumed_better"] = True
        payload["cost_ignored"] = True
        payload["reproducibility_ignored"] = True
        payload["selection_rule"]["minimum_reproducibility"] = -1
        self.assertFalse(validate_model_multiplicity_tradeoff(payload)["valid"])


