class CausalSketchInterpretationRoutingTests(unittest.TestCase):
    def _payload(self):
        return {
            "routing_record_id": "interpretation-routing-1",
            "signal_set_fingerprint": "sha256:signal-set-1",
            "interpreter_role_id": "interpreter",
            "route": "single_pass",
            "sketches": [
                {
                    "causal_sketch_id": "sketch-state-loss",
                    "call_id": "interpret-call-1",
                    "sketch_fingerprint": "sha256:sketch-state-loss",
                    "falsifiable_predictions": [
                        "Persisted state should reduce abandonment after interruption.",
                        "Appeal visibility alone should not restore interrupted progress.",
                    ],
                    "discriminating_observation": "Compare resumption after state persistence without appeal changes.",
                    "prediction_registered_before_outcome": True,
                },
                {
                    "causal_sketch_id": "sketch-recourse-loss",
                    "call_id": "interpret-call-1",
                    "sketch_fingerprint": "sha256:sketch-recourse-loss",
                    "falsifiable_predictions": [
                        "Visible appeal should reduce abandonment after adverse outcomes.",
                        "State persistence alone should not increase successful appeals.",
                    ],
                    "discriminating_observation": "Compare appeal completion after visibility without state changes.",
                    "prediction_registered_before_outcome": True,
                },
            ],
            "predictions_pairwise_separable": True,
            "co_generated_sketch_visibility": True,
            "other_sketches_visible_during_call": True,
            "routing_decided_before_interpretation": True,
            "unseparable_sketches_collapsed_as_plural": False,
            "routing_rationale": "One pass is allowed because each interpretation makes distinct predictions.",
        }

    def test_accepts_one_pass_only_for_distinct_predictions_and_discriminators(self):
        report = validate_causal_sketch_interpretation_routing(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["call_count"], 1)

    def test_rejects_single_pass_when_prediction_sets_or_discriminators_collapse(self):
        payload = self._payload()
        payload["sketches"][1]["falsifiable_predictions"] = list(
            payload["sketches"][0]["falsifiable_predictions"]
        )
        payload["sketches"][1]["discriminating_observation"] = payload["sketches"][0][
            "discriminating_observation"
        ]
        payload["predictions_pairwise_separable"] = False
        self.assertFalse(validate_causal_sketch_interpretation_routing(payload)["valid"])

    def test_accepts_independent_calls_with_unique_call_ids_and_no_cross_visibility(self):
        payload = self._payload()
        payload["route"] = "independent_calls"
