class SharedModelDependenceManifestTests(unittest.TestCase):
    def _payload(self):
        roles = ["interpreter", "inventor", "adversary", "selector", "outcome_analyst"]
        return {
            "assignment_manifest_id": "local-role-manifest-1",
            "role_topology_id": "purpose-cognitive-roles-v1",
            "run_id": "local-purpose-run-1",
            "manifest_fingerprint": "sha256:local-role-manifest-1",
            "role_assignments": [
                {
                    "assignment_id": f"assignment-{role}",
                    "role": role,
                    "provider_id": "provider-local",
                    "model_id": "model-local",
                    "context_partition_id": f"context-{role}",
                    "role_boundary_preserved": True,
                }
                for role in roles
            ],
            "shared_model_groups": [
                {
                    "dependence_group_id": "dependence-model-local",
                    "model_id": "model-local",
                    "roles": roles,
                    "independent_consensus_source_count": 1,
                    "correlated_error_risk_disclosed": True,
                }
            ],
            "evaluation_claims": {
                "shared_model_dependence": True,
                "independent_model_source_count": 1,
                "independent_provider_source_count": 1,
                "role_output_count": 5,
                "independent_consensus_claimed": False,
                "consensus_label": "correlated_role_agreement",
            },
            "local_single_model_testing_allowed": True,
            "role_count_used_as_independence_count": False,
            "manifest_rationale": "Preserve role boundaries while disclosing shared-model correlated errors.",
        }

    def test_accepts_one_model_for_all_roles_when_dependence_is_fully_disclosed(self):
        report = validate_shared_model_dependence_manifest(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["unique_model_count"], 1)
        self.assertTrue(report["shared_model_dependence"])

    def test_requires_exact_shared_model_groups_and_correlated_error_disclosure(self):
        payload = self._payload()
        payload["shared_model_groups"][0]["roles"].pop()
