class SharedAssumptionDominanceFrontierTests(unittest.TestCase):
    def _assumption(self, assumption_id, value):
        return {
            "assumption_id": assumption_id,
            "assumed_value": value,
            "assumption_fingerprint": f"sha256:{assumption_id}:{value}",
            "evidence_fingerprint": f"sha256:evidence:{assumption_id}",
        }

    def _payload(self):
        shared = [
            self._assumption("appeal-arrival-rate", "stable"),
            self._assumption("recovery-latency", "under-one-minute"),
        ]
        different = [
            self._assumption("appeal-arrival-rate", "surging"),
            self._assumption("recovery-latency", "under-one-minute"),
        ]
        return {
            "assumption_gate_id": "shared-assumption-gate-1",
            "decision_structure_id": "plural-decision-structure-1",
            "candidate_set_fingerprint": "sha256:candidate-set-1",
            "candidate_assumptions": [
                {"candidate_id": "candidate-recourse", "assumptions": shared},
                {
                    "candidate_id": "candidate-combined",
                    "assumptions": [dict(item) for item in shared],
                },
                {"candidate_id": "candidate-emergency", "assumptions": different},
            ],
            "pair_assessments": [
                {
                    "pair_id": "pair-recourse-combined",
                    "left_candidate_id": "candidate-recourse",
                    "right_candidate_id": "candidate-combined",
                    "assumptions_shared": True,
                    "dominance_computation_allowed": True,
                    "dominance_assessment_id": "dominance-combined-over-recourse",
                    "assumption_frontier": {},
                    "assumption_difference_treated_as_value_difference": False,
                },
                {
                    "pair_id": "pair-combined-emergency",
                    "left_candidate_id": "candidate-combined",
                    "right_candidate_id": "candidate-emergency",
                    "assumptions_shared": False,
                    "dominance_computation_allowed": False,
                    "dominance_assessment_id": "",
                    "assumption_frontier": {
                        "frontier_id": "frontier-appeal-arrival-rate",
                        "differing_assumption_ids": ["appeal-arrival-rate"],
                        "decision_relevance": "Queue delay depends on whether appeal arrivals remain stable.",
                        "discriminating_evidence_needed": "Observe arrival rate during the bounded probe.",
                        "resolution_trigger": "A representative arrival-rate window closes.",
                        "preserved_as_unresolved": True,
                    },
                    "assumption_difference_treated_as_value_difference": False,
                },
            ],
            "cross_assumption_dominance_allowed": False,
            "unresolved_frontiers_visible_to_selector": True,
            "gate_rationale": "Compare value performance only under the same assumed world.",
        }

    def test_allows_dominance_for_exact_shared_assumptions_and_frontier_for_difference(self):
        report = validate_shared_assumption_dominance_frontier(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["assumption_frontier_count"], 1)

    def test_assumption_sharing_requires_exact_ids_values_and_fingerprints(self):
        payload = self._payload()
        payload["candidate_assumptions"][1]["assumptions"][0]["assumption_fingerprint"] = "sha256:other"
        self.assertFalse(validate_shared_assumption_dominance_frontier(payload)["valid"])

    def test_differing_assumptions_forbid_dominance_and_require_exact_frontier_differences(self):
        payload = self._payload()
        pair = payload["pair_assessments"][1]
        pair["dominance_computation_allowed"] = True
        pair["dominance_assessment_id"] = "false-dominance"
        pair["assumption_frontier"]["differing_assumption_ids"] = ["recovery-latency"]
        pair["assumption_frontier"]["preserved_as_unresolved"] = False
        self.assertFalse(validate_shared_assumption_dominance_frontier(payload)["valid"])

    def test_forbids_cross_assumption_dominance_and_value_relabeling(self):
        payload = self._payload()
        payload["cross_assumption_dominance_allowed"] = True
        payload["unresolved_frontiers_visible_to_selector"] = False
        payload["pair_assessments"][1]["assumption_difference_treated_as_value_difference"] = True
        self.assertFalse(validate_shared_assumption_dominance_frontier(payload)["valid"])


class AdversarialAxisSensitivityReviewTests(unittest.TestCase):
    def _axis(self, candidate_id, axis):
        return {
            "axis": axis,
            "adversarial_question": f"How does {candidate_id} fail on {axis}?",
            "finding": f"Bounded finding for {candidate_id} on {axis}.",
            "supporting_evidence_ids": [f"support-{candidate_id}-{axis}"],
            "opposing_evidence_ids": [f"oppose-{candidate_id}-{axis}"],
            "worst_case_condition": f"Worst credible {axis} condition.",
            "failure_signal": f"Observable {axis} failure signal.",
            "sensitivity_range": {
                "sensitivity_id": f"sensitivity-{candidate_id}-{axis}",
                "assumption_id": f"assumption-{axis}",
                "lower_bound": "registered low bound",
                "upper_bound": "registered high bound",
                "outcome_at_lower_bound": f"{candidate_id} remains viable at low {axis}.",
                "outcome_at_upper_bound": f"{candidate_id} becomes fragile at high {axis}.",
                "selection_flip_threshold": f"Selection flips at registered {axis} threshold.",
                "fragile": axis == "beneficiary_harm",
            },
        }

    def _payload(self):
        candidates = ["candidate-recourse", "candidate-combined"]
        axes = ["constitutional_tension", "causal_robustness", "beneficiary_harm"]
        return {
            "review_set_id": "adversarial-axis-review-1",
            "non_dominated_frontier_fingerprint": "sha256:non-dominated-frontier-1",
            "non_dominated_candidate_ids": candidates,
            "adversarial_axes": axes,
            "candidate_reviews": [
                {
                    "candidate_id": candidate_id,
                    "axis_reviews": [self._axis(candidate_id, axis) for axis in axes],
                    "review_fingerprint": f"sha256:review-{candidate_id}",
                }
                for candidate_id in candidates
            ],
            "aggregate_numerical_score_present": False,
            "axis_tradeoffs_collapsed": False,
            "sensitivity_ranges_visible_to_selector": True,
            "review_rationale": "Expose plural weaknesses and selection fragility without scalar aggregation.",
        }

    def test_accepts_every_non_dominated_candidate_across_every_adversarial_axis(self):
        report = validate_adversarial_axis_sensitivity_review(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["sensitivity_range_count"], 6)

    def test_requires_exact_candidate_and_axis_coverage_without_duplicates(self):
        payload = self._payload()
        payload["candidate_reviews"].pop()
        payload["candidate_reviews"][0]["axis_reviews"].pop()
        payload["candidate_reviews"][0]["axis_reviews"][1]["axis"] = "constitutional_tension"
        self.assertFalse(validate_adversarial_axis_sensitivity_review(payload)["valid"])

    def test_axis_review_requires_both_evidence_sides_worst_case_failure_and_range(self):
        payload = self._payload()
        axis = payload["candidate_reviews"][0]["axis_reviews"][0]
        axis["supporting_evidence_ids"] = []
        axis["opposing_evidence_ids"] = []
        axis["worst_case_condition"] = ""
        axis["failure_signal"] = ""
        axis["sensitivity_range"]["selection_flip_threshold"] = ""
        axis["sensitivity_range"]["fragile"] = "unknown"
        self.assertFalse(validate_adversarial_axis_sensitivity_review(payload)["valid"])

    def test_forbids_aggregate_scores_collapsed_tradeoffs_or_hidden_sensitivity(self):
        payload = self._payload()
        payload["aggregate_numerical_score_present"] = True
        payload["axis_tradeoffs_collapsed"] = True
        payload["sensitivity_ranges_visible_to_selector"] = False
        self.assertFalse(validate_adversarial_axis_sensitivity_review(payload)["valid"])


