        payload["stage_boundaries"][4]["may_bypass_prior_gate"] = True
        payload["selection_frontier"]["selected_candidate_id"] = "candidate-disqualified"
        self.assertFalse(validate_deterministic_model_tournament_implementation(payload)["valid"])

