        payload["sequential_events"][1]["sequence"] = 1
        payload["sequential_events"][2]["revealed_at"] = "2026-08-01T00:00:00Z"
        payload["sequential_events"][0]["pre_next_event_checkpoint"]["frozen_before_next_reveal"] = False
        self.assertFalse(validate_sequential_hidden_causal_proof_case(payload)["valid"])

