class SixDimensionMissionQualityReportTests(unittest.TestCase):
    def _payload(self):
        details = {
            "beneficiary_relevance": {
                "beneficiary_identity": "People with blocked urgent appeals.",
                "current_condition": "Recourse is invisible or delayed.",
                "desired_external_condition": "Urgent recourse is visible and timely.",
                "beneficiary_evidence_id": "evidence-beneficiary-appeals",
            },
            "causal_defensibility": {
                "causal_thesis": "Visible routing exposes blockage before delay compounds.",
                "rival_causal_explanation": "Visibility increases demand and worsens delay.",
                "falsifying_observation": "Visibility rises while clearance-adjusted delay worsens.",
                "causal_evidence_id": "evidence-causal-routing",
            },
            "constitutional_fit": {
                "applicable_clause_ids": ["beneficiary-change", "privacy-minimization"],
                "conflict_assessment": "No hard clause conflict remains.",
                "exception_status": "No exception invoked.",
                "interpretation_trace_id": "interpretation-trace-quality-1",
            },
            "useful_frame_originality": {
                "baseline_frame": "Automate appeal classification.",
                "new_relation": "Receipt visibility is a recourse mechanism before classification.",
                "changed_reachable_action": "Test visible receipts without replacing human review.",
                "lineage_evidence_id": "lineage-evidence-frame-1",
            },
            "feasibility": {
                "binding_constraints": ["Source write latency", "Reviewer capacity"],
                "capability_evidence_id": "capability-evidence-receipts",
                "bounded_strategy_path": "Issue receipts before full classification in one bounded queue.",
                "unresolved_feasibility": "Peak-load receipt consistency remains uncertain.",
            },
            "disconfirmation": {
                "failure_signal": "Visible receipts increase urgent review delay above one day.",
                "discriminating_test": "Compare clearance-adjusted delay in a bounded rollout.",
                "update_or_stop_rule": "Stop and revise the causal thesis on registered harm.",
                "disconfirmation_evidence_id": "disconfirmation-contract-receipts",
            },
        }
        scores = {
            "beneficiary_relevance": 4,
            "causal_defensibility": 3,
            "constitutional_fit": 4,
            "useful_frame_originality": 3,
            "feasibility": 2,
            "disconfirmation": 4,
        }
        return {
            "mission_quality_report_id": "mission-quality-report-1",
            "mission_contract_id": "mission-contract-recourse-1",
            "mission_contract_fingerprint": "sha256:mission-contract-recourse-v4",
            "condition_output_id": "palamedes-output-case-1",
            "condition_output_fingerprint": "sha256:palamedes-output-case-1",
            "evaluation_contract_id": "evaluation-contract-purpose-change-v1",
            "report_fingerprint": "sha256:mission-quality-report-1",
            "dimension_assessments": [
                {
                    "dimension": dimension,
                    "score": score,
                    "rubric_id": f"rubric-{dimension}-v1",
                    "rubric_anchor": f"Precommitted level {score} anchor for {dimension}.",
                    "evidence_artifact_id": f"quality-evidence-{dimension}",
                    "evidence_fingerprint": f"sha256:quality-evidence-{dimension}",
                    "assessment_rationale": f"Evidence supports score {score} on {dimension}.",
                    "uncertainty": f"Residual uncertainty remains for {dimension}.",
                    "improvement_required": f"Next improvement for {dimension}.",
                    "typed_details": typed_details,
                }
                for dimension, typed_details in details.items()
                for score in [scores[dimension]]
            ],
            "dimensions_reported_separately": True,
            "aggregate_quality_score": None,
            "high_dimension_compensates_for_missing_dimension": False,
            "quality_status": "complete",
            "report_rationale": "Preserve six distinct mission-quality judgments and their weaknesses.",
        }

    def test_accepts_six_separate_evidenced_mission_quality_dimensions(self):
        report = validate_six_dimension_mission_quality_report(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["dimension_count"], 6)
        self.assertEqual(report["lowest_scoring_dimensions"], ["feasibility"])

    def test_requires_exact_unique_dimension_coverage_bounded_scores_and_evidence(self):
        payload = self._payload()
        payload["dimension_assessments"][1]["dimension"] = "beneficiary_relevance"
        payload["dimension_assessments"][2]["score"] = 5
        payload["dimension_assessments"][3]["evidence_fingerprint"] = ""
        self.assertFalse(validate_six_dimension_mission_quality_report(payload)["valid"])

    def test_requires_dimension_specific_semantic_evidence(self):
        payload = self._payload()
        for assessment in payload["dimension_assessments"]:
            first_key = next(iter(assessment["typed_details"]))
            assessment["typed_details"][first_key] = [] if isinstance(assessment["typed_details"][first_key], list) else ""
        self.assertFalse(validate_six_dimension_mission_quality_report(payload)["valid"])

    def test_forbids_aggregate_compensation_or_false_complete_status(self):
        payload = self._payload()
        payload["dimensions_reported_separately"] = False
        payload["aggregate_quality_score"] = 3.5
        payload["high_dimension_compensates_for_missing_dimension"] = True
        payload["quality_status"] = "incomplete"
        self.assertFalse(validate_six_dimension_mission_quality_report(payload)["valid"])


class UpstreamHumanCognitionRetirementLedgerTests(unittest.TestCase):
    def _payload(self):
        values = {
            "framing": (60, 10, 3, 1, 0),
            "clarification": (30, 10, 4, 1, 0),
            "approval": (20, 15, 2, 1, 15),
            "correction": (25, 5, 3, 1, 0),
            "intervention": (15, 5, 2, 1, 0),
        }
        categories = []
        for category, (baseline_minutes, palamedes_minutes, baseline_count, palamedes_count, nondelegable) in values.items():
            item = {
                "category": category,
                "baseline_minutes": baseline_minutes,
                "palamedes_minutes": palamedes_minutes,
                "baseline_event_count": baseline_count,
                "palamedes_event_count": palamedes_count,
                "nondelegable_minutes": nondelegable,
                "retired_minutes": max(baseline_minutes - palamedes_minutes, 0),
                "added_minutes": max(palamedes_minutes - baseline_minutes, 0),
                "measurement_record_id": f"labor-measurement-{category}",
                "measurement_method": "Timestamped participant and intervention activity logs.",
                "activity_definition": f"Pre-planner human {category} cognition.",
                "evidence_artifact_id": f"labor-evidence-{category}",
                "measured_before_planner_action": True,
            }
            if category == "approval":
                item["nondelegable_approval_retired"] = False
                item["approval_authority_boundary_id"] = "human-value-authority-boundary"
            categories.append(item)
        return {
            "labor_ledger_id": "upstream-labor-ledger-1",
            "proof_case_id": "historical-replay-appeals-1",
            "baseline_condition_id": "timeboxed-human-baseline",
            "palamedes_condition_id": "palamedes-purpose-engine",
            "measurement_window_start": "2026-08-01T00:00:00Z",
            "planner_action_authorized_at": "2026-08-02T00:00:00Z",
            "measurement_protocol_id": "upstream-labor-measurement-v1",
            "ledger_fingerprint": "sha256:upstream-labor-ledger-1",
            "labor_categories": categories,
            "declared_totals": {
                "baseline_minutes": 150,
                "palamedes_minutes": 45,
                "retired_minutes": 105,
                "added_minutes": 0,
                "net_minutes_retired": 105,
            },
            "post_planner_labor_included": False,
            "nondelegable_human_authority_counted_as_retired": False,
            "labor_retirement_claim_status": "measured",
            "ledger_rationale": "Measure human cognition removed before a planner can act without claiming value authority was automated.",
        }

    def test_accepts_five_category_preplanner_labor_retirement_ledger(self):
        report = validate_upstream_human_cognition_retirement_ledger(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["net_minutes_retired"], 105)

    def test_requires_exact_categories_nonnegative_measurements_and_preplanner_scope(self):
        payload = self._payload()
        payload["labor_categories"][1]["category"] = "framing"
        payload["labor_categories"][2]["baseline_minutes"] = -1
        payload["labor_categories"][3]["measured_before_planner_action"] = False
        payload["planner_action_authorized_at"] = payload["measurement_window_start"]
        self.assertFalse(validate_upstream_human_cognition_retirement_ledger(payload)["valid"])

    def test_requires_exact_retired_added_and_declared_total_arithmetic(self):
        payload = self._payload()
        payload["labor_categories"][0]["retired_minutes"] = 100
        payload["labor_categories"][1]["added_minutes"] = 10
        payload["declared_totals"]["baseline_minutes"] = 1
        payload["declared_totals"]["net_minutes_retired"] = 999
        self.assertFalse(validate_upstream_human_cognition_retirement_ledger(payload)["valid"])

    def test_preserves_nondelegable_approval_and_forbids_hidden_postplanner_labor(self):
        payload = self._payload()
        approval = next(item for item in payload["labor_categories"] if item["category"] == "approval")
        approval["nondelegable_minutes"] = 16
        approval["nondelegable_approval_retired"] = True
        approval["approval_authority_boundary_id"] = ""
        payload["post_planner_labor_included"] = True
        payload["nondelegable_human_authority_counted_as_retired"] = True
        self.assertFalse(validate_upstream_human_cognition_retirement_ledger(payload)["valid"])


class PlannerSemanticReconstructionBurdenReportTests(unittest.TestCase):
    def _payload(self):
        elements = [
            "beneficiary",
            "invariant_meaning",
            "causal_thesis",
            "success_harm_signals",
            "non_goals",
            "authority",
        ]
        condition_statuses = {
            "human": ["clarified", "clarified", "reconstructed", "clarified", "reconstructed", "clarified"],
            "one_shot_agent": ["directly_understood", "clarified", "reconstructed", "clarified", "reconstructed", "clarified"],
            "palamedes": ["directly_understood", "directly_understood", "directly_understood", "directly_understood", "clarified", "directly_understood"],
        }
        reports = []
        for condition, statuses in condition_statuses.items():
            semantic_elements = []
            for element, status in zip(elements, statuses):
                minutes = 0 if status == "directly_understood" else 5
                questions = 1 if status == "clarified" else 0
                lookups = 1 if status in {"reconstructed", "clarified", "corrected"} else 0
                corrections = 1 if status == "corrected" else 0
                semantic_elements.append({
                    "element": element,
                    "status": status,
                    "reconstruction_minutes": minutes,
                    "clarification_question_count": questions,
                    "source_lookup_count": lookups,
                    "semantic_correction_count": corrections,
                    "measurement_record_id": f"burden-measurement-{condition}-{element}",
                    "evidence_artifact_id": f"burden-evidence-{condition}-{element}",
                    "burden_rationale": f"Planner {status.replace('_', ' ')} {element}.",
                })
            totals = {
                field: sum(item[field] for item in semantic_elements)
                for field in (
                    "reconstruction_minutes",
                    "clarification_question_count",
                    "source_lookup_count",
                    "semantic_correction_count",
                )
            }
            reports.append({
                "condition": condition,
                "source_handoff_artifact_id": f"handoff-{condition}",
                "source_handoff_fingerprint": f"sha256:handoff-{condition}",
                "planner_id": f"planner-{condition}",
                "session_id": f"planner-session-{condition}",
                "handoff_received_at": "2026-08-01T00:00:00Z",
                "strategy_ready_at": "2026-08-01T01:00:00Z",
                "session_evidence_artifact_id": f"session-evidence-{condition}",
                "semantic_elements": semantic_elements,
                "declared_totals": totals,
                "minutes_to_strategy_ready": totals["reconstruction_minutes"] + 10,
                "burden_measured_after_handoff_before_strategy": True,
            })
        return {
            "planner_burden_report_id": "planner-burden-report-1",
            "proof_case_id": "historical-replay-appeals-1",
            "measurement_protocol_id": "planner-burden-measurement-v1",
            "report_fingerprint": "sha256:planner-burden-report-1",
            "condition_reports": reports,
            "planner_satisfaction_substitutes_for_measurement": False,
            "unlogged_clarification_treated_as_zero": False,
            "condition_results_reported_separately": True,
            "report_rationale": "Measure semantic reconstruction after handoff before a planner can propose strategy.",
        }

    def test_accepts_six_element_measured_planner_burden_for_all_conditions(self):
        report = validate_planner_semantic_reconstruction_burden_report(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["condition_count"], 3)

    def test_requires_all_conditions_and_unique_complete_semantic_elements(self):
        payload = self._payload()
        payload["condition_reports"][1]["condition"] = "human"
        payload["condition_reports"][2]["semantic_elements"][1]["element"] = "beneficiary"
        payload["condition_reports"][0]["strategy_ready_at"] = payload["condition_reports"][0]["handoff_received_at"]
        self.assertFalse(validate_planner_semantic_reconstruction_burden_report(payload)["valid"])

    def test_enforces_status_specific_burden_and_exact_total_arithmetic(self):
        payload = self._payload()
        human = payload["condition_reports"][0]
        human["semantic_elements"][0]["status"] = "directly_understood"
        human["semantic_elements"][1]["clarification_question_count"] = 0
        human["semantic_elements"][2]["status"] = "corrected"
        human["declared_totals"]["reconstruction_minutes"] = 0
        self.assertFalse(validate_planner_semantic_reconstruction_burden_report(payload)["valid"])

    def test_forbids_satisfaction_proxy_unlogged_zero_or_collapsed_condition_result(self):
        payload = self._payload()
        payload["condition_reports"][0]["burden_measured_after_handoff_before_strategy"] = False
        payload["planner_satisfaction_substitutes_for_measurement"] = True
        payload["unlogged_clarification_treated_as_zero"] = True
        payload["condition_results_reported_separately"] = False
        self.assertFalse(validate_planner_semantic_reconstruction_burden_report(payload)["valid"])


class MultiHorizonOutcomeQualityReportTests(unittest.TestCase):
    def _payload(self):
        dimensions = {
            "beneficiary_change": (
                "Share of urgent appellants receiving timely visible recourse.",
                "Baseline 40 percent.",
                "At least 90 percent without subgroup regression.",
            ),
            "side_effects": (
                "Review delay, privacy exposure, and displaced burden.",
                "Registered pre-strategy harm baseline.",
                "No harm threshold crossed.",
            ),
            "sustainability": (
                "Outcome persistence without exceptional staffing or hidden subsidy.",
                "Normal operating resource envelope.",
                "Outcome remains inside normal resource and maintenance limits.",
            ),
            "option_preservation": (
                "Reversible alternatives and future mission options retained.",
                "Pre-strategy option inventory.",
                "No evidence-relevant option irreversibly removed without authority.",
            ),
        }
        horizon_specs = [
            ("short", 14, True),
            ("medium", 60, True),
            ("long", 180, False),
        ]
        horizon_assessments = []
        for horizon, day, reached in horizon_specs:
            items = []
            for dimension, (question, baseline, target) in dimensions.items():
                item = {
                    "dimension": dimension,
                    "metric_or_question": question,
                    "baseline_or_reference": baseline,
                    "target_or_boundary": target,
                    "measurement_status": "observed" if reached else "pending",
                    "observed_value": f"Observed {dimension} at day {day}." if reached else "",
                    "evidence_artifact_id": f"outcome-evidence-{horizon}-{dimension}" if reached else "",
                    "evidence_fingerprint": f"sha256:outcome-evidence-{horizon}-{dimension}" if reached else "",
                    "assessment": f"Assess {dimension} against its independent boundary." if reached else "",
                    "uncertainty": f"Residual uncertainty for {horizon} {dimension}.",
                    "next_observation_at": "" if reached else "2027-01-28T00:00:00Z",
                    "pending_reason": "" if reached else "The long horizon has not elapsed.",
                }
                items.append(item)
            horizon_assessments.append({
                "horizon": horizon,
                "day_from_strategy_start": day,
                "scheduled_at": f"2026-{8 + min(day // 30, 4):02d}-15T00:00:00Z",
                "horizon_definition": f"{horizon.title()} outcome horizon at day {day}.",
                "assessment_artifact_id": f"outcome-assessment-{horizon}",
                "horizon_reached": reached,
                "dimensions": items,
            })
        return {
            "outcome_quality_report_id": "outcome-quality-report-1",
            "mission_contract_id": "mission-contract-recourse-1",
            "mission_contract_fingerprint": "sha256:mission-contract-recourse-v4",
            "strategy_version_id": "strategy-recourse-v3",
            "strategy_fingerprint": "sha256:strategy-recourse-v3",
            "outcome_protocol_id": "multi-horizon-outcome-protocol-v1",
            "report_fingerprint": "sha256:outcome-quality-report-1",
            "horizon_assessments": horizon_assessments,
            "early_success_extrapolated_to_later_horizons": False,
            "side_effects_netted_into_beneficiary_change": False,
            "sustainability_assumed_from_initial_delivery": False,
            "lost_options_ignored": False,
            "dimensions_reported_separately": True,
            "report_rationale": "Measure intended and unintended consequence durability without collapsing time or dimensions.",
        }

    def test_accepts_four_dimension_outcomes_at_ordered_short_medium_long_horizons(self):
        report = validate_multi_horizon_outcome_quality_report(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["observed_dimension_count"], 8)
        self.assertEqual(report["pending_dimension_count"], 4)

    def test_requires_ordered_increasing_horizons_and_exact_dimension_coverage(self):
        payload = self._payload()
        payload["horizon_assessments"][1]["horizon"] = "short"
        payload["horizon_assessments"][2]["day_from_strategy_start"] = 30
        payload["horizon_assessments"][0]["dimensions"][1]["dimension"] = "beneficiary_change"
        self.assertFalse(validate_multi_horizon_outcome_quality_report(payload)["valid"])

    def test_requires_observed_evidence_only_for_reached_horizons_and_pending_schedule_otherwise(self):
        payload = self._payload()
        observed = payload["horizon_assessments"][0]["dimensions"][0]
        observed["evidence_fingerprint"] = ""
        observed["next_observation_at"] = "later"
        pending = payload["horizon_assessments"][2]["dimensions"][0]
        pending["measurement_status"] = "observed"
        pending["observed_value"] = "guessed success"
        pending["next_observation_at"] = ""
        self.assertFalse(validate_multi_horizon_outcome_quality_report(payload)["valid"])

    def test_forbids_temporal_extrapolation_dimension_netting_or_ignored_options(self):
        payload = self._payload()
        payload["early_success_extrapolated_to_later_horizons"] = True
        payload["side_effects_netted_into_beneficiary_change"] = True
        payload["sustainability_assumed_from_initial_delivery"] = True
        payload["lost_options_ignored"] = True
        payload["dimensions_reported_separately"] = False
        self.assertFalse(validate_multi_horizon_outcome_quality_report(payload)["valid"])


