class IntegratedMissionMetricThesisTests(unittest.TestCase):
    def _payload(self):
        values = {
            "mission_consequence": (0.5, 0.7, "score", "higher_better"),
            "retired_cognition": (0, 70, "minutes", "higher_better"),
            "compute": (10, 25, "normalized_compute_units", "lower_better"),
            "total_human_labor": (120, 60, "minutes", "lower_better"),
            "calibration": (0.20, 0.10, "brier_score", "lower_better"),
            "harm": (2, 1, "registered_harm_count", "lower_better"),
            "replaceability": (0.9, 0.4, "retained_value_after_ablation", "diagnostic_only"),
        }
        dimensions = []
        for name, (baseline, palamedes, unit, direction) in values.items():
            dimensions.append({
                "dimension": name,
                "metric_definition": f"Registered definition for {name}.",
                "unit": unit,
                "baseline_value": baseline,
                "palamedes_value": palamedes,
                "direction": direction,
                "baseline_evidence_artifact_id": f"baseline-evidence-{name}",
                "palamedes_evidence_artifact_id": f"palamedes-evidence-{name}",
                "measurement_rationale": f"Expose {name} without substitution.",
                "reported_separately": True,
                "disqualifying_boundary_crossed": False,
            })
        return {
            "metric_thesis_id": "metric-thesis-1",
            "proof_dataset_id": "external-proof-dataset-v1",
            "baseline_condition_id": "equal-information-agent",
            "palamedes_condition_id": "palamedes-purpose-engine",
            "measurement_protocol_id": "mission-metric-thesis-v1",
            "scorecard_fingerprint": "sha256:metric-thesis-1",
            "equal_information_verified": True,
            "dimensions": dimensions,
            "constitutional_violation_count": 0,
            "evidence_eligible": True,
            "single_composite_score_authoritative": False,
            "compute_or_labor_hidden": False,
            "harm_nettable_against_benefit": False,
            "replaceability_omitted": False,
            "scorecard_rationale": "Preserve every proof dimension and its resource or safety boundary.",
        }

    def test_accepts_seven_separate_dimensions_under_equal_information(self):
        report = validate_integrated_mission_metric_thesis(self._payload())
        self.assertTrue(report["valid"])
        self.assertEqual(report["dimension_count"], 7)
        self.assertTrue(report["evidence_eligible"])

    def test_requires_exact_unique_dimensions_numeric_values_and_evidence(self):
        payload = self._payload()
        payload["dimensions"][1]["dimension"] = "mission_consequence"
        payload["dimensions"][2]["baseline_value"] = "hidden"
        payload["dimensions"][3]["palamedes_evidence_artifact_id"] = ""
        self.assertFalse(validate_integrated_mission_metric_thesis(payload)["valid"])

    def test_disqualifying_harm_or_constitutional_violation_blocks_eligibility(self):
        payload = self._payload()
        harm = next(item for item in payload["dimensions"] if item["dimension"] == "harm")
        harm["disqualifying_boundary_crossed"] = True
        payload["constitutional_violation_count"] = 1
        self.assertFalse(validate_integrated_mission_metric_thesis(payload)["valid"])

    def test_forbids_composite_resource_hiding_harm_netting_or_replaceability_omission(self):
        payload = self._payload()
        payload["single_composite_score_authoritative"] = True
        payload["compute_or_labor_hidden"] = True
        payload["harm_nettable_against_benefit"] = True
        payload["replaceability_omitted"] = True
        payload["dimensions"][0]["reported_separately"] = False
        self.assertFalse(validate_integrated_mission_metric_thesis(payload)["valid"])


class ExperimentalContractStableStateIsolationTests(unittest.TestCase):
    def _payload(self):
        stable_core = {
            "schema_version": "0.5.0",
            "goal": "Preserve recourse",
            "success_metric": "Visible appeal before action",
            "plan_tasks": ["Compile an accepted mission"],
            "execution_tasks": [],
        }
        source = {
            "stable_plan_reference": {
                "plan_id": "plan-recourse-1",
                "schema_version": "0.5.0",
                "fingerprint": "sha256:stable-plan-recourse-1",
            },
            "missions": [{"mission_id": "mission-recourse-1"}],
        }
        return {
            "isolation_report_id": "experimental-isolation-1",
            "stable_plan_schema_version": "0.5.0",
            "stable_plan_fingerprint_before": "sha256:stable-plan-recourse-1",
            "stable_plan_fingerprint_after": "sha256:stable-plan-recourse-1",
            "stable_core_before": stable_core,
            "stable_core_after": dict(stable_core),
            "experimental_source_state": source,
            "experimental_migrated_state": migrate_experimental_mission_state(source),
            "migration_evidence_artifact_id": "migration-evidence-1",
            "report_fingerprint": "sha256:experimental-isolation-1",
            "experimental_payload_embedded_in_stable_plan": False,
            "stable_migration_function_changed": False,
            "stable_schema_required_fields_changed": False,
            "report_rationale": "Migrate a separate experimental envelope while stable plan bytes and semantics remain unchanged.",
        }

    def test_migrates_defaults_behind_version_without_mutating_source(self):
        payload = self._payload()
        source_before = deepcopy(payload["experimental_source_state"])
        migrated = migrate_experimental_mission_state(payload["experimental_source_state"])
        self.assertEqual(payload["experimental_source_state"], source_before)
        self.assertEqual(migrated["experimental_contract_version"], EXPERIMENTAL_MISSION_CONTRACT_VERSION)
        self.assertEqual(migrated["observations"], [])
        self.assertEqual(migrated["interpretations"], [])
        self.assertEqual(migrated["outcome_returns"], [])
        self.assertFalse(migrated["migration_metadata"]["stable_core_mutated"])

    def test_accepts_stable_core_preservation_and_idempotent_migration(self):
        report = validate_experimental_contract_stable_state_isolation(self._payload())
        self.assertTrue(report["valid"])
        self.assertTrue(report["stable_core_preserved"])
        self.assertTrue(report["migration_idempotent"])

    def test_rejects_stable_state_or_fingerprint_changes_and_embedding(self):
        payload = self._payload()
        payload["stable_core_after"]["goal"] = "Expanded Palamedes"
        payload["stable_plan_fingerprint_after"] = "sha256:changed"
        payload["experimental_payload_embedded_in_stable_plan"] = True
        payload["stable_migration_function_changed"] = True
        payload["stable_schema_required_fields_changed"] = True
        self.assertFalse(validate_experimental_contract_stable_state_isolation(payload)["valid"])

    def test_rejects_future_version_embedded_plan_or_nondeterministic_output(self):
        payload = self._payload()
        payload["experimental_source_state"]["experimental_contract_version"] = "mission-experimental/99"
        payload["experimental_source_state"]["stable_plan_reference"]["goal"] = "embedded stable plan"
        payload["experimental_migrated_state"]["missions"].append({"mission_id": "invented"})
        self.assertFalse(validate_experimental_contract_stable_state_isolation(payload)["valid"])


