    def test_rejects_deleted_reordered_or_reassigned_outcomes(self):
        payload = self._payload()
        payload["restore_record"]["outcome_observations"].reverse()
        payload["restore_record"]["outcome_observations"][0]["source_selection_revision_id"] = "selection-revision-2"
        payload["restore_record"]["outcome_observation_count_after"] = 1
        payload["restore_record"]["outcomes_deleted_by_restore"] = True
        payload["restore_record"]["later_outcomes_reassigned_to_restored_selection"] = True
        self.assertFalse(validate_selection_restore_outcome_preservation(payload)["valid"])


